def match_template(tokens, segment_ids, segment_positions, templates):
    L = max(len(t) for t in templates)
    prefixes = ["u:",": tokens == "u:"]
# Each layer l checks if the input matches t[:l+1]
for l in range(1, L):
    just_MATCHed = select Prev(prefixs[-1], segment_ids, segment_positions)
    ever_MATCHed = frac Prev(prefixes[-1], segment_ids, segment_positions)
    new_MATCHes = {}
    for t in templates:
        if len(t) <= 1: continue
            if t[l] == "0": 
                new_MATCHs[t[:l+1]] = ever_MATCHed[t[:l]] > 0
            elif t[l-1] == "0" and t[l] == "1": 
                new_MATCHs[t[:l+1]] = prefixes[-1][t[:l]]
            elif t[l-1] == "0": 
                new_MATCHs[t[:l+1]] = prefixes[-1][t[:l]] & (tokens == t[l])
            elif t[l] == "1": 
                new_MATCHs[t[:l+1]] = just_MATCHed[t[:l]]
            else:
                new_MATCHs[t[:l+1]] = just_MATCHed[t[:l]] & (tokens == t[l])
    prefixes.append(new_MATCHes)
# For each template, identify the longest matching prefix at each position.
states = {}
for t in templates:
    s = np.stack[m[t[:l+1]] for l, m in zip(range(len(t)), prefixes)]
    ind = np.arange(s.shape[0])
    states[t] = (ind[:, None] * s).max(0)
return states 
